// src/components/Header.jsx

import React, { useState } from 'react';
import { Link } from 'react-router-dom'; // 1. IMPORT Link

const styles = {
  header: {
    backgroundColor: '#1a202c',
    color: '#e2e8f0',
    padding: '20px 40px',
    borderBottom: '1px solid #2d3748',
    boxShadow: '0 2px 4px rgba(0, 0, 0, 0.2)',
    position: 'sticky',
    top: 0,
    zIndex: 1000,
    transition: 'background-color 0.3s ease-in-out',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  titleContainer: {
    display: 'flex',
    flexDirection: 'column',
  },
  title: {
    fontSize: '2.2rem',
    fontWeight: '700',
    margin: 0,
    color: '#a7ffeb',
  },
  subtitle: {
    fontSize: '1.1rem',
    marginTop: '2px',
    fontStyle: 'italic',
    color: '#a0aec0',
  },
  nav: {
    display: 'flex',
    gap: '30px',
  },
  navLink: {
    color: '#e2e8f0',
    textDecoration: 'none',
    fontSize: '1rem',
    fontWeight: '500',
    position: 'relative',
    transition: 'color 0.3s ease',
  },
  navLinkHover: {
    color: '#ffffff',
  },
  navLinkUnderline: {
    position: 'absolute',
    bottom: '-5px',
    left: 0,
    right: 0,
    height: '2px',
    backgroundColor: '#a7ffeb',
    transform: 'scaleX(0)',
    transition: 'transform 0.3s ease-in-out',
  },
};

// 2. Navigation items updated for routing
const navItems = [
    { name: 'Home', path: '/' },
    { name: 'About Us', path: '#about' }, // These can be updated to actual routes later
    { name: 'Services', path: '#services' },
    { name: 'Enquiry Form', path: '/enquiry' }, // 3. ADDED NEW LINK FOR THE FORM
];

const Header = () => {
  const [hoveredLink, setHoveredLink] = useState(null);

  const handleMouseEnter = (linkName) => {
    setHoveredLink(linkName);
  };

  const handleMouseLeave = () => {
    setHoveredLink(null);
  };

  return (
    <header style={styles.header}>
      <div style={styles.container}>
        <div style={styles.titleContainer}>
          {/* Title link now navigates to home */}
          <Link to="/" style={{ textDecoration: 'none' }}>
            <h1 style={styles.title}>Karpagam Clinic</h1>
          </Link>
          <p style={styles.subtitle}>Your Health, Our Priority</p>
        </div>
        <nav style={styles.nav}>
          {/* 4. MAPPED OVER THE NEW ITEMS AND USED Link COMPONENT */}
          {navItems.map((item) => (
            <Link
              key={item.name}
              to={item.path}
              style={{
                ...styles.navLink,
                ...(hoveredLink === item.name ? styles.navLinkHover : {}),
              }}
              onMouseEnter={() => handleMouseEnter(item.name)}
              onMouseLeave={handleMouseLeave}
            >
              {item.name}
              <span
                style={{
                  ...styles.navLinkUnderline,
                  transform: hoveredLink === item.name ? 'scaleX(1)' : 'scaleX(0)',
                }}
              />
            </Link>
          ))}
        </nav>
      </div>
    </header>
  );
};

export default Header;
